    def _hourly_tick(self) -> None:
        """å‘¨æœŸæ£€æŸ¥æ•´ç‚¹æŠ¥æ—¶ï¼Œå·¥ä½œæŠ¥å‘Šæ”¹ä¸ºç”¨æˆ·æŒ‰éœ€æ‰“å¼€ã€‚"""

